// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
        c.SetLogFile(address(new LogFile()));
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(address actor, uint128 depositAmt, uint128 amount) public {
        vm.assume(actor != address(c) && actor != address(this));
        uint256 am = bound(uint256(amount), 0, uint256(depositAmt));

        vm.deal(actor, uint256(depositAmt));
        vm.prank(actor);
        c.Deposit{value: uint256(depositAmt)}();

        uint256 before = c.balances(actor);
        vm.prank(actor);
        c.Collect(uint256(am));

        assertTrue(c.balances(actor) == before - uint256(am));
    }
}
